 await click('#step-reverse');assert.match(await page.evaluate('document.querySelector("#message").textContent'),/INVALID_STATE/);await click('#compensation');env.f.kernel.fault=async p=>{if(p==='control-after-send')throw Error('bf27 lost compensation acknowledgement');};await click('#step-reverse');env.f.kernel.fault=async()=>{};await result('WITHDRAW_UNKNOWN');await page.screenshot('journey-bf27-step1-unknown');
