 await signIn('operator');await open();await page.fill('#department','synthetic-hr');await page.fill('#reference',payload.reference);await page.fill('#task',payload.task);await page.click('#offer');await page.until('document.querySelector("#state").textContent==="OFFERED"');await signIn('other');await open();assert.match(await page.evaluate('document.querySelector("#detail").textContent'),new RegExp(payload.task));await page.click('#accept');await page.until('document.querySelector("#state").textContent==="ACCEPTED"');await page.click('#step-dispatch');await page.until('document.querySelector("#step-detail").textContent.includes("ACCEPTED")');await page.screenshot('journey-bf32-authorized-recipient');
 await env.f.call('publisher','grant',{principal:'reader',scopes:[second],operations:['read','search','approve'],fields:['CONFIDENTIAL']});await signIn('reader');await open();assert.equal(await page.evaluate('document.querySelector("#detail").textContent'),'');await page.screenshot('journey-bf32-missing-classification');
 await signIn('operator');await open();await page.click('#cancel');await page.until('document.querySelector("#state").textContent==="CANCELLED"');await signIn('other');await open();await page.click('#compensation');await page.until('document.querySelector("#history").textContent.includes("handoffCompensateApprove")');await page.click('#step-reverse');await page.until('document.querySelector("#step-detail").textContent.includes("WITHDRAWN")');await page.screenshot('journey-bf32-recovered');const ledger=await env.web.ledger();assert.deepEqual(ledger.map(x=>({applied:x.applied,withdrawn:x.withdrawn})),[{applied:1,withdrawn:1}]);
 const output=process.env.ENTERPRISE_SUITE_OUTPUT??'evidence/enterprise/browser';await mkdir(output,{recursive:true});await writeFile(output+'/journey-bf32-browser.json',JSON.stringify({id,denied,browser:await page.send('Browser.getVersion'),ledger,requests:env.web.requests},null,2)+'\n');
