export async function rightClassificationBrowser(){
 const env=await localEnvironment(),page=await browser(),id='bf33-'+randomUUID(),strict={...scope,classification:'STRICT'},secret={subject:'bf33-ui-secret-subject',material:'bf33-ui-secret-material',evidence:'bf33-ui-secret-version'},responses=[];
 const click=selector=>page.evaluate(`document.querySelector(${JSON.stringify(selector)}).onclick()`);
 const grant=(principal,fields)=>env.f.call('publisher','grant',{principal,scopes:[strict],operations:['read','search','records','audit','recovery'],fields});
 const signIn=async who=>{await page.navigate(env.gateway.origin+'/login');await page.until('!!document.querySelector("select[name=account]")');await page.fill('select[name=account]',who);await page.click('button');await page.until(`document.querySelector('#identity')?.textContent==='ログイン中: ${who}'`);await page.click('a[href="/controls"]');await page.until(`document.querySelector('#identity')?.textContent==='ログイン中: ${who}'`);await page.fill('#kind','right');await page.evaluate('document.querySelector("#kind").dispatchEvent(new Event("change"))');await page.until('document.querySelector("#message").textContent.includes("保存")');};
 const open=async()=>{await page.fill('#target',id);await click('#open');await page.until('document.querySelector("#state").textContent.length>0||document.querySelector("#message").textContent.includes("PERMISSION_DENIED")');};
 const api=async operation=>page.evaluate(`(async()=>{const s=await(await fetch('/session')).json(),r=await fetch('/api',{method:'POST',headers:{'content-type':'application/json','x-csrf-token':s.csrf},body:JSON.stringify({contractVersion:'2.0.0',operation:${JSON.stringify(operation)},key:crypto.randomUUID(),body:${JSON.stringify({id})}})});return {status:r.status,body:await r.json()}})()`);
 try{
 await env.f.owner.query("UPDATE enterprise_grants SET scopes=$1 WHERE principal='publisher'",[JSON.stringify([scope,strict])]);await grant('manager',['CONFIDENTIAL','STRICT']);await grant('reader',['CONFIDENTIAL']);
 await signIn('manager');await page.fill('#new-id',id);for(const [field,value] of Object.entries(secret))await page.fill('#'+field,value);await page.click('#create button');await page.until('document.querySelector("#state").textContent==="GRANTED"');await page.screenshot('right-bf33-created');
 await signIn('reader');await open();const observed=await api('controlRead');responses.push(observed);await page.screenshot('right-bf33-unclassified');console.log('BF-33 browser observation',JSON.stringify(observed));assert.equal(observed.status,403);for(const value of Object.values(secret))assert.equal((await page.evaluate('document.body.textContent')).includes(value),false);assert.equal(await page.evaluate('document.querySelector("#records").children.length'),0);
 for(const button of ['#audit','#check','#revoke']){await click(button);await page.until('document.querySelector("#message").textContent.includes("PERMISSION_DENIED")');}assert.equal(await page.evaluate('document.querySelector("#detail").textContent+document.querySelector("#audit-records").textContent'),'');
 await grant('reader',['RESTRICTED']);await signIn('reader');await open();assert.match(await page.evaluate('document.querySelector("#detail").textContent'),/分類: STRICT/);for(const value of Object.values(secret))assert.ok((await page.evaluate('document.querySelector("#detail").textContent')).includes(value));await click('#check');await page.until('document.querySelector("#message").textContent.includes("保存")');await click('#audit');await page.until('document.querySelector("#audit-records").textContent.length>0');responses.push(await api('controlAudit'));await page.screenshot('right-bf33-authorized');
 await grant('reader',['CONFIDENTIAL']);await click('#open');await page.until('document.querySelector("#message").textContent.includes("PERMISSION_DENIED")');assert.equal(await page.evaluate('document.querySelector("#detail").textContent+document.querySelector("#history").textContent+document.querySelector("#audit-records").textContent'),'');await page.screenshot('right-bf33-revoked-classification');
 await signIn('manager');await open();await click('#revoke');await page.until('document.querySelector("#state").textContent==="REVOKED"');await click('#check');await page.until('document.querySelector("#message").textContent.includes("PERMISSION_DENIED")');await page.screenshot('right-bf33-consent-revoked');assert.equal(env.web.requests.length,0);
 const output=process.env.ENTERPRISE_SUITE_OUTPUT??'evidence/enterprise/browser';await mkdir(output,{recursive:true});await writeFile(output+'/right-bf33-browser.json',JSON.stringify({id,browser:await page.send('Browser.getVersion'),responses,requests:env.web.requests,ledger:await env.web.ledger()},null,2)+'\n');
 }finally{await page.close();await env.close();}
}

export async function releaseAuthorityBrowser(){
 const env=await localEnvironment(),page=await browser(),id='bf34-'+randomUUID(),secret={...scope,departmentId:'bf34-secret-department',caseId:'bf34-unrelated-strict-case',classification:'STRICT'},responses=[];
 const {operations}=await import('../../scripts/enterprise/fixture.mjs'),fields=['PUBLIC','INTERNAL','CONFIDENTIAL','STRICT','RESTRICTED'];
 const grant=(principal,ops=operations,labels=fields)=>env.f.call('publisher','grant',{principal,scopes:principal==='reader'?[scope]:[scope,secret],operations:ops,fields:labels});
 const signIn=async who=>{await page.navigate(env.gateway.origin+'/login');await page.until('!!document.querySelector("select[name=account]")');await page.fill('select[name=account]',who);await page.click('button');await page.until(`document.querySelector('#identity')?.textContent==='ログイン中: ${who}'`);await page.click('a[href="/controls"]');await page.until(`document.querySelector('#identity')?.textContent==='ログイン中: ${who}'`);await page.evaluate(`window.bf34=[];const fetchOriginal=window.fetch;window.fetch=async(...args)=>{const r=await fetchOriginal(...args);if(args[0]==='/api')window.bf34.push({request:JSON.parse(args[1].body),status:r.status,body:await r.clone().json()});return r;}`);await page.fill('#kind','release');await page.evaluate('document.querySelector("#kind").onchange()');};
 const click=async selector=>page.evaluate(`document.querySelector(${JSON.stringify(selector)}).onclick()`);
 const open=async()=>{await page.fill('#target',id);await click('#open');};
 const clean=async()=>{const batch=await page.evaluate('window.bf34');responses.push(...batch);const result=batch.filter(v=>v.request.operation==='controlRead').at(-1);assert.equal(result.status,200);for(const marker of [secret.caseId,secret.departmentId,'"authority"','"scopes"','"fields"','"policyVersion"','"binding"'])assert.equal(JSON.stringify(result.body).includes(marker),false,marker);assert.equal((await page.evaluate('document.body.textContent')).includes(secret.caseId),false);return result.body.result;};
 try{
 await env.f.owner.query("UPDATE enterprise_grants SET scopes=$1 WHERE principal='publisher'",[JSON.stringify([scope,secret])]);for(const who of ['operator','manager','reviewer','publisher'])await grant(who);await grant('reader',['read','search'],['INTERNAL','CONFIDENTIAL']);
 const info=await source(env.f),right=rightBody();right.material='object:'+(await env.f.call('manager','controlRead',{id:info,purpose:'disclosure'})).data.sources[0].id;await env.f.call('manager','rightGrant',right);
 await signIn('operator');await page.fill('#new-id',id);await page.fill('#source',info);await page.fill('#right',right.id);await page.fill('#channels','web');await page.click('#create button');await page.until('document.querySelector("#state").textContent==="DRAFT"');
 for(const [who,role] of [['manager','legal'],['reviewer','pr'],['publisher','ir']]){await signIn(who);await open();await page.fill('#role',role);await click('#approve');}
 await signIn('reader');await open();await page.screenshot('release-bf34-reader');const first=await clean();assert.deepEqual(first.data.approvals,[{role:'legal',subject:'manager'},{role:'pr',subject:'reviewer'},{role:'ir',subject:'publisher'}]);assert.match(await page.evaluate('document.querySelector("#detail").textContent'),/承認: legal \/ manager/);await click('#audit');assert.match(await page.evaluate('document.querySelector("#message").textContent'),/PERMISSION_DENIED/);await page.screenshot('release-bf34-audit-denied');
 await grant('reader',['read','search','audit'],['INTERNAL','CONFIDENTIAL']);await open();await click('#audit');assert.ok((await page.evaluate('document.querySelector("#audit-records").textContent')).length);await clean();assert.equal(JSON.stringify(await page.evaluate('window.bf34')).includes(secret.caseId),false);await page.screenshot('release-bf34-auditor');
 await grant('reader',['read','search','audit'],['INTERNAL']);await open();assert.match(await page.evaluate('document.querySelector("#message").textContent'),/PERMISSION_DENIED/);assert.equal(await page.evaluate('document.querySelector("#detail").textContent'), '');assert.equal(await page.evaluate('document.querySelector("#audit-records").textContent'),'');await page.screenshot('release-bf34-revoked');
 await signIn('publisher');await open();env.web.loseNext();await click('#dispatch');await clean();assert.match(await page.evaluate('document.querySelector("#detail").textContent'),/UNKNOWN/);await click('#reconcile');await clean();assert.equal(await page.evaluate('document.querySelector("#state").textContent'),'ACCEPTED');
 await signIn('operator');await open();await click('#withdraw');for(const [who,role] of [['manager','legal'],['reviewer','pr'],['publisher','ir']]){await signIn(who);await open();await page.fill('#role',role);await click('#approve');}const approved=await clean();assert.deepEqual(approved.data.withdrawalApprovals,first.data.approvals);assert.match(await page.evaluate('document.querySelector("#detail").textContent'),/撤回承認: legal \/ manager/);await page.screenshot('release-bf34-withdrawal-approved');await click('#reverse');await clean();assert.equal(await page.evaluate('document.querySelector("#state").textContent'),'WITHDRAWN');await page.screenshot('release-bf34-withdrawn');assert.deepEqual((await env.web.ledger()).map(v=>({applied:v.applied,withdrawn:v.withdrawn})),[{applied:1,withdrawn:1}]);
 }finally{const output=process.env.ENTERPRISE_SUITE_OUTPUT??'evidence/enterprise/browser';await mkdir(output,{recursive:true});await writeFile(output+'/release-bf34-browser.json',JSON.stringify({id,userAgent:await page.evaluate('navigator.userAgent'),responses,latest:await page.evaluate('window.bf34??[]'),requests:env.web.requests,ledger:await env.web.ledger()},null,2));await page.close();await env.close();}
}
